return {["sort"]=0,["roomList"]={{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[幽冥鬼府]],["permission"]=1,["fullName"]=[[幽冥鬼府(fb615_18)]],["enterable"]=1,["up"]=[[fb615_15]],["dsc"]=[[弟子试炼之所，多以战养战、试炼蛊法，令弟子自相残杀，在生死搏斗间提升实力，选出其中优秀者，场面惨不忍睹，故此间弟子十不存一。]],["down"]=[[fb615_21]],["visible"]=1,["unit4"]=[[25cyshopyouming]],["dirIndex"]=0,["unit3"]=[[22youmingcynpc]],["unit2"]=[[npc08]],["unit1"]=[[shengwang23]],["canLeave"]=1,["id"]=[[fb615_18]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[判魂居]],["permission"]=1,["fullName"]=[[判魂居(fb615_19)]],["enterable"]=1,["up"]=[[fb615_16]],["dsc"]=[[判魂居划分为二，前者，入门之处形如衙堂，左右绘牛头马面，无常勾魂索命。素日里是为审判叛教之徒而设，但凡定罪，无不割破叛徒手腕，以叛徒之血书写其罪。后者，则毒草遍生，直通枯骨园。]],["down"]=[[fb615_22]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc02]],["canLeave"]=1,["id"]=[[fb615_19]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[招魂黑幡]],["permission"]=1,["left"]=[[fb615_09]],["enterable"]=1,["dsc"]=[[取无底洞壁幽草辅以混沌之气炼成，挥动此幡可遮天蔽日，令天地失色，日月无光。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[招魂黑幡(fb615_10)]],["canLeave"]=1,["id"]=[[fb615_10]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb615_12]],["connectPoint"]=0,["name"]=[[招魂黄幡]],["permission"]=1,["enterable"]=1,["dsc"]=[[取黄泉孤魂辅以息土炼成，用之可令海水倒灌，黄河决堤。]],["fullName"]=[[招魂黄幡(fb615_11)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc10j]],["unit2"]=[[npc09j]],["unit1"]=[[npc07j]],["canLeave"]=1,["id"]=[[fb615_11]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb615_13]],["connectPoint"]=0,["name"]=[[幽冥暗河]],["permission"]=1,["left"]=[[fb615_11]],["enterable"]=1,["up"]=[[fb615_09]],["dsc"]=[[幽深不见底，水汽寒意逼人，鸿毛不浮，水中不时传来凄厉啼声，令人胆寒。]],["down"]=[[fb615_15]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[幽冥暗河(fb615_12)]],["canLeave"]=1,["id"]=[[fb615_12]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb615_30]],["connectPoint"]=0,["name"]=[[轮回台]],["permission"]=1,["left"]