"name"]=[[枯骨园]],["permission"]=1,["enterable"]=1,["up"]=[[fb615_19]],["dsc"]=[[枯骨园是为埋葬叛徒仇家尸体而设，且埋葬极为潦草，常有野物刨出尸体啃食，断臂残肢，满地皆是。不过对于幽冥弟子，见怪不怪，反倒成为居所中的一处奇景。]],["down"]=[[fb615_25]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[枯骨园(fb615_22)]],["canLeave"]=1,["id"]=[[fb615_22]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[幽冥鬼居]],["permission"]=1,["enterable"]=1,["up"]=[[fb615_28]],["dsc"]=[[居内悬挂黑线长帘，上面绑缚细小铜铃，掀起时叮铃铃作响。一把罗汉床横放，旁边的花盆内种有彼岸花，推窗可见枯骨园内枯骨，夜半之时似乎总能听到啼哭之声。]],["fullName"]=[[幽冥鬼居(fb615_29)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc06g]],["canLeave"]=1,["id"]=[[fb615_29]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[曼殊沙华园]],["permission"]=1,["fullName"]=[[曼殊沙华园(fb615_28)]],["enterable"]=1,["up"]=[[fb615_27]],["dsc"]=[[常言曼殊沙华生于忘川，一株两花，雌雄不同开。不知为何，这座院子种满了曼莎珠华，颜色艳丽，香气醉人。]],["down"]=[[fb615_29]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc06d]],["canLeave"]=1,["id"]=[[fb615_28]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[无魂殿]],["permission"]=1,["enterable"]=1,["up"]=[[fb615_18]],["dsc"]=[[殿中红毯顺两侧白玉石梯铺设，直通枯骨宝座。宝座旁又各立长明灯四盏，招魂幡四幡。座下席位并列，中间房梁悬挂头骨灯，常人入此殿望而生畏。]],["down"]=[[fb615_24]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[无魂殿(fb615_21)]],["canLeave"]=1,["id"]=[[fb615_21]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[枯骨园]],["permission"]=1,["fullName"]=[[枯骨园(fb615_20)]],["enterable"]=1,["up"]=[[fb615_17]],["dsc"]=[[枯骨园是为埋葬叛徒仇家尸体而设，且埋葬极为潦草，常有野物刨出尸体啃食，断臂残肢，满地皆是。不过对于幽冥弟子，见怪不怪，反倒成为居所中的一处奇景。]],["down"]=[[fb615_23]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc06e]],["canLeave"]=1,["id"]=[[fb615_20]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb615_10]],["connectPoint"]=0,["name"]=[[幽冥暗河]],["permission"]=1,["left"]=[[fb615_08]],["enterable"]=1,["up"]=[[fb615_06]],["dsc"]=[[幽深不见底，水汽寒意逼人，鸿毛不浮，水中不时传来凄厉啼声，令人胆寒。]],["down"]=[[fb615_12]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[幽冥暗